namespace TutorFlow.Core.Autorizacion;

public sealed class PoliticaAcceso
{
    private readonly DecisionAcceso _decisionPermitida = DecisionAcceso.Permitir();

    public DecisionAcceso EvaluarIdentidad(Usuario usuario, DirectorioAcademico directorio) =>
        ExisteIdentidad(usuario, directorio)
            ? _decisionPermitida
            : DecisionAcceso.Denegar(MotivoDenegacion.IdentidadInvalida);

    public DecisionAcceso EvaluarPregunta(Usuario usuario, string pregunta, DirectorioAcademico directorio)
    {
        var texto = NormalizadorTexto.Normalizar(pregunta);
        var motivo = MotivoTercero(usuario, texto, directorio)
            ?? MotivoPrograma(usuario, texto, directorio)
            ?? MotivoAgregado(usuario, texto);
        return motivo is { } denegado ? DecisionAcceso.Denegar(denegado) : DecisionAcceso.Permitir();
    }

    public DecisionAcceso EvaluarLecturaEstudiante(Usuario usuario, string estudianteId, DirectorioAcademico directorio) =>
        PuedeLeerEstudiante(usuario, estudianteId, directorio)
            ? DecisionAcceso.Permitir()
            : DecisionAcceso.Denegar(MotivoDenegacion.HerramientaIdAjeno);

    public IReadOnlyList<string> ProgramasAutorizados(Usuario usuario, DirectorioAcademico directorio) =>
        EvaluarIdentidad(usuario, directorio).Permitido ? AmbitoPersonal.ProgramasDe(usuario, directorio) : [];

    public IReadOnlyList<string> IdsPersonasAutorizadas(Usuario usuario, DirectorioAcademico directorio)
    {
        if (!EvaluarIdentidad(usuario, directorio).Permitido)
        {
            return [];
        }

        var ambito = AmbitoPersonal.De(usuario, directorio);
        return [.. directorio.Estudiantes.Select(e => e.Id)
            .Concat(directorio.Coordinadores.Select(c => c.Id))
            .Where(id => ambito.ClavesDeNombre.Contains(AmbitoPersonal.Clave(id)))];
    }

    private static bool ExisteIdentidad(Usuario usuario, DirectorioAcademico directorio) => usuario.Rol switch
    {
        Rol.Estudiante => Identificadores.EsIdEstudiante(usuario.Id) && directorio.Estudiantes.Any(e => e.Id == usuario.Id),
        Rol.Coordinador => Identificadores.EsIdCoordinador(usuario.Id) && directorio.Coordinadores.Any(c => c.Id == usuario.Id),
        _ => false
    };

    private bool PuedeLeerEstudiante(Usuario usuario, string estudianteId, DirectorioAcademico directorio)
    {
        var estudiante = directorio.Estudiantes.FirstOrDefault(e => e.Id == estudianteId);
        if (estudiante is null || !Identificadores.EsIdEstudiante(estudianteId))
        {
            return false;
        }

        return usuario.Rol == Rol.Estudiante
            ? usuario.Id == estudianteId
            : ProgramasAutorizados(usuario, directorio).Contains(estudiante.ProgramaId);
    }

    private static MotivoDenegacion? MotivoTercero(Usuario usuario, string texto, DirectorioAcademico directorio) =>
        DetectorTerceros.MencionaTercero(usuario, texto, directorio) ? MotivoDenegacion.TerceroMencionado : null;

    private MotivoDenegacion? MotivoPrograma(Usuario usuario, string texto, DirectorioAcademico directorio) =>
        usuario.Rol == Rol.Coordinador && DetectorProgramas.MencionaProgramaAjeno(texto, ProgramasAutorizados(usuario, directorio), directorio)
            ? MotivoDenegacion.ProgramaAjeno
            : null;

    private static MotivoDenegacion? MotivoAgregado(Usuario usuario, string texto) =>
        usuario.Rol == Rol.Estudiante && DetectorAgregados.PideAgregados(texto) ? MotivoDenegacion.Agregado : null;
}
using TutorFlow.Core.Academico;
using TutorFlow.Core.Autorizacion;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

public sealed record ContextoUsuario(Usuario Usuario, DirectorioAcademico Directorio);

public sealed record ResultadoHerramienta(string Contenido, bool IdAjeno, string? IdSolicitado = null)
{
    public static ResultadoHerramienta Texto(string contenido) => new(contenido, false);

    public static ResultadoHerramienta Denegado(string idSolicitado) => new(string.Empty, true, idSolicitado);
}

public sealed class HerramientasAsistente
{
    public const string DatosBasicos = "consultar_datos_basicos";
    public const string Notas = "consultar_notas";
    public const string Cortes = "consultar_cortes";
    public const string Asistencia = "consultar_asistencia";
    public const string Programa = "consultar_programa";
    public const string Estudiante = "consultar_estudiante";
    public const string ParametroEstudianteId = "estudianteId";
    public const string ParametroAsignatura = "asignatura";

    private static readonly IReadOnlyList<HerramientaLlm> HerramientasDeEstudiante =
    [
        new(Notas, "Consulta las definitivas de cada asignatura, el promedio ponderado del periodo, la prueba académica, la habilitación y la elegibilidad de beca de la persona que pregunta, ya calculados. Úsala para preguntas sobre notas, promedio, asignaturas perdidas, habilitación o beca.", []),
        new(Asistencia, "Consulta las inasistencias, las faltas permitidas y las faltas restantes de cada asignatura de la persona que pregunta. Úsala para preguntas sobre asistencia o faltas.", []),
        new(DatosBasicos, "Consulta el nombre, el programa y el coordinador del programa de la persona que pregunta. Úsala para preguntas sobre quién es su coordinador o a qué programa pertenece.", []),
        new(Cortes, "Consulta las notas de los tres cortes de una asignatura de la persona que pregunta. Úsala solo cuando pregunten por la nota de un corte concreto.", [new ParametroHerramienta(ParametroAsignatura, "Nombre o código de la asignatura.", true)])
    ];

    private static readonly IReadOnlyList<HerramientaLlm> HerramientasDeCoordinador =
    [
        new(Programa, "Consulta, para cada estudiante de los programas a cargo del coordinador, el promedio, la prueba académica, las asignaturas perdidas, las asignaturas sin definitiva y la asistencia sin registro. Úsala para listados y conteos del programa.", []),
        new(Estudiante, "Consulta el detalle de notas y asistencia de un estudiante de los programas del coordinador. Úsala cuando pregunten por un estudiante concreto.", [new ParametroHerramienta(ParametroEstudianteId, "Identificador del estudiante: las letras EST, un guion y tres dígitos.", true)])
    ];

    private readonly IApiAcademica _apiAcademica;
    private readonly PoliticaAcceso _politicaAcceso;
    private readonly Dictionary<string, Func<SolicitudHerramienta, Task<ResultadoHerramienta>>> _manejadores;

    public HerramientasAsistente(IApiAcademica apiAcademica, PoliticaAcceso politicaAcceso)
    {
        _apiAcademica = apiAcademica;
        _politicaAcceso = politicaAcceso;
        _manejadores = new Dictionary<string, Func<SolicitudHerramienta, Task<ResultadoHerramienta>>>
        {
            [DatosBasicos] = ConsultarDatosBasicos,
            [Notas] = ConsultarNotas,
            [Cortes] = ConsultarCortes,
            [Asistencia] = ConsultarAsistencia,
            [Programa] = ConsultarPrograma,
            [Estudiante] = ConsultarEstudiante
        };
    }

    public static IReadOnlyList<string> NombresInternos { get; } =
        [.. HerramientasDeEstudiante.Concat(HerramientasDeCoordinador).Select(herramienta => herramienta.Nombre)];

    public static IReadOnlyList<HerramientaLlm> Definir(Rol rol) =>
        rol == Rol.Coordinador ? HerramientasDeCoordinador : HerramientasDeEstudiante;

    public async Task<ResultadoHerramienta> EjecutarAsync(
        LlamadaHerramienta llamada,
        ContextoUsuario contexto,
        RegistroConsultas registro,
        CancellationToken cancellationToken)
    {
        if (!EstaDisponible(llamada.Nombre, contexto.Usuario.Rol) || !_manejadores.TryGetValue(llamada.Nombre, out var manejador))
        {
            return ResultadoHerramienta.Texto(Textos.HerramientaNoDisponible);
        }

        var estudianteId = ArgumentosHerramienta.LeerTexto(llamada.ArgumentosJson, ParametroEstudianteId);
        if (EsLecturaAjena(contexto, estudianteId))
        {
            return ResultadoHerramienta.Denegado(IdAuditable(estudianteId));
        }

        var asignatura = ArgumentosHerramienta.LeerTexto(llamada.ArgumentosJson, ParametroAsignatura);
        return await manejador(new SolicitudHerramienta(contexto, registro, estudianteId, asignatura, cancellationToken));
    }

    private static string IdAuditable(string? idSolicitado) =>
        idSolicitado is not null && (Identificadores.EsIdEstudiante(idSolicitado) || Identificadores.EsIdCoordinador(idSolicitado))
            ? idSolicitado
            : Textos.FormatoInvalido;

    private static bool EstaDisponible(string nombre, Rol rol) =>
        Definir(rol).Any(herramienta => herramienta.Nombre == nombre);

    private bool EsLecturaAjena(ContextoUsuario contexto, string? estudianteId) =>
        estudianteId is not null
        && !_politicaAcceso.EvaluarLecturaEstudiante(contexto.Usuario, estudianteId, contexto.Directorio).Permitido;

    private Task<ResultadoHerramienta> ConsultarDatosBasicos(SolicitudHerramienta solicitud)
    {
        var estudiante = solicitud.Contexto.Directorio.Estudiantes.First(e => e.Id == solicitud.Contexto.Usuario.Id);
        var contenido = FormateadorDatos.DatosBasicos(estudiante, solicitud.Contexto.Directorio);
        solicitud.Registro.RegistrarDatos([DatosLeidos.SinAsignatura(estudiante.Id, estudiante.ProgramaId, RecursoConsultado.DatosBasicos)]);
        return Task.FromResult(Responder(solicitud, contenido, estudiante.Id, [RecursoConsultado.DatosBasicos], Textos.SeccionDatosBasicos));
    }

    private async Task<ResultadoHerramienta> ConsultarNotas(SolicitudHerramienta solicitud)
    {
        var id = solicitud.Contexto.Usuario.Id;
        var resumen = await ResumirAsync(id, solicitud.CancellationToken);
        solicitud.Registro.RegistrarDatos(DatosLeidos.PorAsignatura(resumen, ProgramaDe(solicitud, id), RecursoConsultado.Notas, RecursoConsultado.Asistencia));
        solicitud.Registro.RegistrarResumen(resumen);
        return Responder(solicitud, ConReglas(solicitud, FormateadorDatos.Notas(resumen), ReglasAplicadas.DeNotas([resumen])), id, [RecursoConsultado.Notas, RecursoConsultado.Asistencia], Textos.SeccionNotas);
    }

    private async Task<ResultadoHerramienta> ConsultarCortes(SolicitudHerramienta solicitud)
    {
        if (string.IsNullOrWhiteSpace(solicitud.Asignatura))
        {
            return ResultadoHerramienta.Texto(Textos.FaltaAsignatura);
        }

        var id = solicitud.Contexto.Usuario.Id;
        var notas = await _apiAcademica.ObtenerNotasAsync(id, solicitud.CancellationToken);
        var contenido = FormateadorDatos.Cortes(notas, solicitud.Asignatura);
        var codigos = FormateadorDatos.BuscarAsignaturas(notas, solicitud.Asignatura).Select(nota => nota.Codigo);
        solicitud.Registro.RegistrarDatos(DatosLeidos.PorCodigos(id, ProgramaDe(solicitud, id), codigos, RecursoConsultado.Notas));
        return Responder(solicitud, contenido, id, [RecursoConsultado.Notas], Textos.SeccionNotas);
    }

    private async Task<ResultadoHerramienta> ConsultarAsistencia(SolicitudHerramienta solicitud)
    {
        var id = solicitud.Contexto.Usuario.Id;
        var resumen = await ResumirAsync(id, solicitud.CancellationToken);
        solicitud.Registro.RegistrarDatos(DatosLeidos.PorAsignatura(resumen, ProgramaDe(solicitud, id), RecursoConsultado.Notas, RecursoConsultado.Asistencia));
        solicitud.Registro.RegistrarResumen(resumen);
        return Responder(solicitud, ConReglas(solicitud, FormateadorDatos.Asistencia(resumen), ReglasAplicadas.DeAsistencia([resumen])), id, [RecursoConsultado.Notas, RecursoConsultado.Asistencia], Textos.SeccionAsistencia);
    }

    private async Task<ResultadoHerramienta> ConsultarEstudiante(SolicitudHerramienta solicitud)
    {
        if (string.IsNullOrEmpty(solicitud.EstudianteId))
        {
            return ResultadoHerramienta.Texto(Textos.FaltaIdentificadorEstudiante);
        }

        var directorio = solicitud.Contexto.Directorio;
        var estudiante = directorio.Estudiantes.First(e => e.Id == solicitud.EstudianteId);
        var resumen = await ResumirAsync(estudiante.Id, solicitud.CancellationToken);
        var detalle = string.Join("\n", FormateadorDatos.DatosBasicos(estudiante, directorio), FormateadorDatos.Notas(resumen), FormateadorDatos.Asistencia(resumen));
        var contenido = ConReglas(solicitud, detalle, ReglasAplicadas.DeNotasYAsistencia([resumen]));
        var recursos = new[] { RecursoConsultado.DatosBasicos, RecursoConsultado.Notas, RecursoConsultado.Asistencia };
        solicitud.Registro.Registrar(estudiante.Id, recursos, new Cita(Textos.DocumentoDatosEstudiante, Textos.SeccionAsistencia));
        solicitud.Registro.RegistrarDatos(DatosDeEstudiante(estudiante, resumen, RecursoConsultado.DatosBasicos));
        solicitud.Registro.RegistrarResumen(resumen);
        return Responder(solicitud, contenido, estudiante.Id, recursos, Textos.SeccionNotas);
    }

    private async Task<ResultadoHerramienta> ConsultarPrograma(SolicitudHerramienta solicitud)
    {
        var programas = _politicaAcceso.ProgramasAutorizados(solicitud.Contexto.Usuario, solicitud.Contexto.Directorio);
        if (programas.Count == 0)
        {
            return ResultadoHerramienta.Texto(Textos.SinProgramasAsignados);
        }

        var bloques = new List<string>();
        foreach (var programa in solicitud.Contexto.Directorio.Programas.Where(p => programas.Contains(p.Id)))
        {
            bloques.Add(await DescribirProgramaAsync(solicitud, programa));
        }

        return ResultadoHerramienta.Texto(string.Join("\n\n", bloques));
    }

    private async Task<string> DescribirProgramaAsync(SolicitudHerramienta solicitud, Programa programa)
    {
        var estudiantes = solicitud.Contexto.Directorio.Estudiantes.Where(e => e.ProgramaId == programa.Id).ToList();
        var lineas = new List<string> { FormateadorDatos.EncabezadoPrograma(programa, estudiantes.Count) };
        var resumenes = new List<ResumenEstudiante>();
        foreach (var estudiante in estudiantes)
        {
            var resumen = await ResumirAsync(estudiante.Id, solicitud.CancellationToken);
            resumenes.Add(resumen);
            lineas.Add(FormateadorDatos.LineaDePrograma(estudiante, resumen));
            solicitud.Registro.Registrar(estudiante.Id, [RecursoConsultado.Programa, RecursoConsultado.Notas, RecursoConsultado.Asistencia], null);
            solicitud.Registro.RegistrarDatos(DatosDeEstudiante(estudiante, resumen, RecursoConsultado.Programa));
            solicitud.Registro.RegistrarResumen(resumen);
        }

        solicitud.Registro.RegistrarCita(new Cita(Textos.DocumentoDatosPrograma, programa.Id));
        var contenido = ConReglas(solicitud, string.Join("\n", lineas), ReglasAplicadas.DePrograma(resumenes));
        return FormateadorDatos.Delimitar($"{Textos.DocumentoDatosPrograma} · {programa.Id}", contenido);
    }

    private static string ProgramaDe(SolicitudHerramienta solicitud, string estudianteId) =>
        solicitud.Contexto.Directorio.Estudiantes.First(e => e.Id == estudianteId).ProgramaId;

    private static IEnumerable<DatoConsultado> DatosDeEstudiante(Estudiante estudiante, ResumenEstudiante resumen, RecursoConsultado recursoSinAsignatura) =>
        DatosLeidos.PorAsignatura(resumen, estudiante.ProgramaId, RecursoConsultado.Notas, RecursoConsultado.Asistencia)
            .Prepend(DatosLeidos.SinAsignatura(estudiante.Id, estudiante.ProgramaId, recursoSinAsignatura));

    private static string ConReglas(SolicitudHerramienta solicitud, string contenido, IReadOnlyList<int> entradas)
    {
        solicitud.Registro.RegistrarReglas(entradas);
        var reglas = ReglasAplicadas.Citas(entradas);
        return reglas.Count == 0 ? contenido : $"{contenido}\n{FormateadorResumen.LineaDeReglas(reglas)}";
    }

    private static ResultadoHerramienta Responder(
        SolicitudHerramienta solicitud,
        string contenido,
        string estudianteId,
        IEnumerable<RecursoConsultado> recursos,
        string seccion)
    {
        var cita = new Cita(Textos.DocumentoDatosEstudiante, seccion);
        solicitud.Registro.Registrar(estudianteId, recursos, cita);
        return ResultadoHerramienta.Texto(FormateadorDatos.Delimitar($"{cita.Documento} · {cita.Seccion}", contenido));
    }

    private Task<ResumenEstudiante> ResumirAsync(string estudianteId, CancellationToken cancellationToken) =>
        ResumenesAcademicos.ResumirAsync(_apiAcademica, estudianteId, cancellationToken);

    private sealed record SolicitudHerramienta(
        ContextoUsuario Contexto,
        RegistroConsultas Registro,
        string? EstudianteId,
        string? Asignatura,
        CancellationToken CancellationToken);
}
using System.Text.RegularExpressions;

namespace TutorFlow.Core.Autorizacion;

public static partial class Identificadores
{
    public static bool EsIdEstudiante(string? id) => id is not null && IdEstudiante().IsMatch(id);

    public static bool EsIdCoordinador(string? id) => id is not null && IdCoordinador().IsMatch(id);

    public static bool EsIdPrograma(string? id) => id is not null && IdPrograma().IsMatch(id);

    [GeneratedRegex(@"^EST-[0-9]{3}\z", RegexOptions.None, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex IdEstudiante();

    [GeneratedRegex(@"^COORD-[0-9]{2}\z", RegexOptions.None, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex IdCoordinador();

    [GeneratedRegex(@"^[A-Z]{2,5}(-[A-Z]{2,5})?\z", RegexOptions.None, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex IdPrograma();
}
using System.Text.RegularExpressions;

namespace TutorFlow.Core.Autorizacion;

internal readonly record struct MencionPersona(string Clave, int Inicio, int Fin);

internal readonly record struct MencionDeAutorizado(string Id, int Inicio, int Fin);

public static partial class DetectorTerceros
{
    private const string MarcadorTercero = "[TERCERO]";
    private const int MinimoTokensNombreCompleto = 2;
    private static readonly string[] PrefijosId = ["est", "coord"];

    public static bool MencionaTercero(Usuario usuario, string textoNormalizado, DirectorioAcademico directorio)
    {
        var ambito = AmbitoPersonal.De(usuario, directorio);
        var tokens = TokenizadorTexto.Tokenizar(textoNormalizado);
        return MencionesDeId(tokens, directorio).Any(mencion => !ambito.ClavesDeId.Contains(mencion.Clave))
            || MencionesDeNombre(tokens, directorio).Any(mencion => !ambito.ClavesDeNombre.Contains(mencion.Clave));
    }

    public static bool TieneFormaDeIdPersona(string textoNormalizado, DirectorioAcademico directorio) =>
        MencionesDeId(TokenizadorTexto.Tokenizar(textoNormalizado), directorio).Count > 0;

    public static bool MencionaIdFueraDe(string textoNormalizado, IReadOnlyCollection<string> idsAutorizados, DirectorioAcademico directorio)
    {
        var clavesAutorizadas = idsAutorizados.Select(AmbitoPersonal.Clave).ToHashSet();
        return MencionesDeId(TokenizadorTexto.Tokenizar(textoNormalizado), directorio)
            .Any(mencion => !clavesAutorizadas.Contains(mencion.Clave));
    }

    internal static IReadOnlyList<MencionDeAutorizado> MencionesDeAutorizados(
        string texto,
        IReadOnlyCollection<string> idsAutorizados,
        DirectorioAcademico directorio)
    {
        var tokens = TokenizadorTexto.Tokenizar(texto);
        var idPorClave = idsAutorizados.Distinct().ToDictionary(AmbitoPersonal.Clave);
        return [.. MencionesDeId(tokens, directorio)
            .Concat(MencionesDeNombre(tokens, directorio))
            .Where(mencion => idPorClave.ContainsKey(mencion.Clave))
            .Select(mencion => new MencionDeAutorizado(idPorClave[mencion.Clave], mencion.Inicio, mencion.Fin))
            .OrderBy(mencion => mencion.Inicio)];
    }

    public static bool MencionaNombreCompleto(string idPersona, string textoNormalizado, DirectorioAcademico directorio)
    {
        var clave = AmbitoPersonal.Clave(idPersona);
        return MencionesDeNombre(TokenizadorTexto.Tokenizar(textoNormalizado), directorio).Any(mencion => mencion.Clave == clave);
    }

    public static IReadOnlyList<string> PersonasMencionadas(string textoNormalizado, DirectorioAcademico directorio)
    {
        var tokens = TokenizadorTexto.Tokenizar(textoNormalizado);
        var idsPorClave = PersonasDelRegistro(directorio)
            .ToDictionary(persona => AmbitoPersonal.Clave(persona.Id), persona => persona.Id);
        return MencionesDeId(tokens, directorio)
            .Concat(MencionesDeNombre(tokens, directorio))
            .Where(mencion => idsPorClave.ContainsKey(mencion.Clave))
            .Select(mencion => idsPorClave[mencion.Clave])
            .Distinct()
            .ToList();
    }

    public static string EnmascararTerceros(Usuario usuario, string pregunta, DirectorioAcademico directorio)
    {
        var ambito = AmbitoPersonal.De(usuario, directorio);
        var tokens = TokenizadorTexto.Tokenizar(pregunta);
        var porId = MencionesDeId(tokens, directorio).Where(mencion => !ambito.ClavesDeId.Contains(mencion.Clave));
        var porNombre = MencionesDeNombre(tokens, directorio).Where(mencion => !ambito.ClavesDeNombre.Contains(mencion.Clave));
        var terceros = porId.Concat(porNombre).OrderByDescending(mencion => mencion.Inicio).ToList();
        return Reemplazar(pregunta, terceros);
    }

    public static string EnmascararPersonas(string pregunta, DirectorioAcademico directorio)
    {
        var tokens = TokenizadorTexto.Tokenizar(pregunta);
        var personas = MencionesDeId(tokens, directorio).Concat(MencionesDeNombre(tokens, directorio));
        return Reemplazar(pregunta, [.. personas.OrderByDescending(mencion => mencion.Inicio)]);
    }

    private static string Reemplazar(string texto, List<MencionPersona> mencionesDeFinAInicio)
    {
        var limite = texto.Length;
        foreach (var mencion in mencionesDeFinAInicio.Where(mencion => mencion.Fin <= limite))
        {
            texto = string.Concat(texto.AsSpan(0, mencion.Inicio), MarcadorTercero, texto.AsSpan(mencion.Fin));
            limite = mencion.Inicio;
        }

        return texto;
    }

    private static List<MencionPersona> MencionesDeId(IReadOnlyList<TokenTexto> tokens, DirectorioAcademico directorio)
    {
        var codigos = directorio.CodigosAsignatura.Select(AmbitoPersonal.Clave).ToHashSet();
        return Enumerable.Range(0, tokens.Count)
            .Select(indice => MencionDeIdEn(tokens, indice))
            .OfType<MencionPersona>()
            .Where(mencion => !codigos.Contains(mencion.Clave))
            .ToList();
    }

    private static MencionPersona? MencionDeIdEn(IReadOnlyList<TokenTexto> tokens, int indice)
    {
        var actual = tokens[indice];
        if (IdPegado().IsMatch(actual.Valor))
        {
            return new MencionPersona(actual.Valor, actual.Inicio, actual.Fin);
        }

        var hayDigitos = indice + 1 < tokens.Count && SoloDigitos().IsMatch(tokens[indice + 1].Valor);
        return hayDigitos && PrefijosId.Contains(actual.Valor)
            ? new MencionPersona(actual.Valor + tokens[indice + 1].Valor, actual.Inicio, tokens[indice + 1].Fin)
            : null;
    }

    private static List<MencionPersona> MencionesDeNombre(IReadOnlyList<TokenTexto> tokens, DirectorioAcademico directorio) =>
        PersonasDelRegistro(directorio)
            .SelectMany(persona => MencionesDe(tokens, persona))
            .ToList();

    private static IEnumerable<MencionPersona> MencionesDe(IReadOnlyList<TokenTexto> tokens, (string Id, string Nombre) persona)
    {
        var nombre = TokenizadorTexto.Valores(persona.Nombre);
        if (nombre.Count < MinimoTokensNombreCompleto)
        {
            return [];
        }

        IReadOnlyList<string>[] ordenes = [nombre, [.. nombre.Reverse()]];
        return ordenes.SelectMany(orden => TokenizadorTexto.BuscarSecuencias(tokens, orden)
            .Select(indice => new MencionPersona(
                AmbitoPersonal.Clave(persona.Id),
                tokens[indice].Inicio,
                tokens[indice + orden.Count - 1].Fin)));
    }

    private static IEnumerable<(string Id, string Nombre)> PersonasDelRegistro(DirectorioAcademico directorio) =>
        directorio.Estudiantes.Select(estudiante => (estudiante.Id, estudiante.Nombre))
            .Concat(directorio.Coordinadores.Select(coordinador => (coordinador.Id, coordinador.Nombre)));

    [GeneratedRegex(@"^(est|coord)[0-9]+\z", RegexOptions.None, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex IdPegado();

    [GeneratedRegex(@"^[0-9]+\z", RegexOptions.None, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex SoloDigitos();
}

